// Calculate average profit or loss for a given list of transactions
double calculateAverageProfitOrLoss(List<Transaction> transactions) {
  int totalProfitOrLoss = 0;
  for (var transaction in transactions) {
    totalProfitOrLoss += transaction.profitOrLoss;
  }
  return totalProfitOrLoss / transactions.length;
}

