const carSizes = require('./data').carSizes;

function recommendCarSize(height) {
  const heightInches = parseFloat(height) * 12; // Convert height from feet to inches

  for (const size in carSizes) {
    const range = carSizes[size].heightRange.split('-');
    const minHeight = parseFloat(range[0]) * 12;
    const maxHeight = parseFloat(range[1]) * 12;

    if (heightInches >= minHeight && heightInches <= maxHeight) {
      return carSizes[size];
    }
  }

  throw new Error("Unable to find suitable car size.");
}

