```typescript
import { Injectable } from '@nestjs/common';
import { Model } from 'mongoose';
import { User } from './user.interface';
import { Person, Address, Contact } from './schemas';

@Injectable()
export class UserService {
  constructor(
    private readonly personModel: Model<Person>,
    private readonly addressModel: Model<Address>,
    private readonly contactModel: Model<Contact>,
  ) {}

  async createUser(user: User): Promise<User> {
    const { person, address, contact } = user;
    const newPerson = await this.personModel.create(person);
    const newAddress = await this.addressModel.create(address);
    const newContact = await this.contactModel.create(contact);
    return { ...user, person: newPerson, address: newAddress, contact: newContact };
  }
}
```

