```csharp
using System;
using System.Net.Http;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace RestServiceWrapper
{
    public abstract class RestServiceBase
    {
        protected readonly string BaseUrl;
        protected readonly string AuthToken;

        private readonly HttpClient _httpClient;

        protected RestServiceBase(string baseUrl, string authToken)
        {
            BaseUrl = baseUrl ?? throw new ArgumentNullException(nameof(baseUrl));
            AuthToken = authToken ?? throw new ArgumentNullException(nameof(authToken));

            _httpClient = new HttpClient();
            _httpClient.DefaultRequestHeaders.Authorization = $"Bearer {AuthToken}";
        }

        protected async Task<TResult> SendAsync<TResult>(string requestUrl, Func<HttpContent, CancellationToken, Task<TResult>> messageHandler)
        {
            var uri = new Uri($"{BaseUrl}{requestUrl}", UriKind.Absolute);
            using (var response = await _httpClient.SendAsync(messageHandler(null, CancellationToken.None), uri, CancellationToken.None))
            {
                response.EnsureSuccessStatusCode();
                return await response.Content.ReadFromJsonAsync<TResult>();
            }
        }

        protected async Task SendAsync(string requestUrl)
        {
            await SendAsync(requestUrl, message => MessageToHttpContent(message));
        }

        protected virtual Task<HttpContent> MessageToHttpContent(HttpContent message)
        {
            if (message == null)
            {
                return Task.FromResult((HttpContent)null);
            }

            var content = message.Content;
            var isFormData = content?.IsMimeMultipartContent() == true;
            var bodyStream = isFormData ? await message.Content.ReadAsStreamAsync() : await message.Content.ReadAsStringAsync();
            var httpContent = new StringContent(bodyStream, Encoding.UTF8, "application/json");
            httpContent.Headers.Clear();

