function ipv6Score(data) {
  const sourceIp = data.sourceIP;
  const destIp = data.destinationIP;

  // validate ipv6 format
  const regex = /^([\da-f]{1,4}:){7}([\da-f]{1,4})$/;
  if (!regex.test(sourceIp) || !regex.test(destIp)) {
    return 0;
  }

  return 100;
}

function httpScore(data) {
  return data.port === 80 ? 50 : 0;
}

